//! Unit tests for `PermissionLevel`: its total order, default, `Display`
//! form, and the exact wire representation each variant is pinned to.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::PermissionLevel;

#[test]
fn levels_are_totally_ordered_from_none_to_dangerous() {
    // Enforcement compares levels with `<` to reject a tool whose required
    // level exceeds the caller's maximum, so this ordering is load-bearing.
    assert!(PermissionLevel::None < PermissionLevel::ReadOnly);
    assert!(PermissionLevel::ReadOnly < PermissionLevel::Write);
    assert!(PermissionLevel::Write < PermissionLevel::Execute);
    assert!(PermissionLevel::Execute < PermissionLevel::Dangerous);
}

#[test]
fn default_is_read_only() {
    assert_eq!(PermissionLevel::default(), PermissionLevel::ReadOnly);
}

#[test]
fn display_matches_the_variant_name() {
    assert_eq!(PermissionLevel::None.to_string(), "None");
    assert_eq!(PermissionLevel::ReadOnly.to_string(), "ReadOnly");
    assert_eq!(PermissionLevel::Write.to_string(), "Write");
    assert_eq!(PermissionLevel::Execute.to_string(), "Execute");
    assert_eq!(PermissionLevel::Dangerous.to_string(), "Dangerous");
}

#[test]
fn levels_round_trip_through_json() {
    for level in [
        PermissionLevel::None,
        PermissionLevel::ReadOnly,
        PermissionLevel::Write,
        PermissionLevel::Execute,
        PermissionLevel::Dangerous,
    ] {
        let encoded = serde_json::to_string(&level).expect("serializable");
        let back: PermissionLevel = serde_json::from_str(&encoded).expect("deserializable");
        assert_eq!(back, level);
    }
}

#[test]
fn levels_are_pinned_to_their_exact_wire_names() {
    // A round-trip alone only proves the encoder and decoder currently agree
    // with *each other* — it still passes if a `serde` rename quietly changes
    // what gets persisted. Pin the literal strings, in both directions, so a
    // rename that would silently corrupt an on-disk transcript or an RPC
    // payload already carrying `"ReadOnly"` fails here instead.
    let cases = [
        (PermissionLevel::None, "\"None\""),
        (PermissionLevel::ReadOnly, "\"ReadOnly\""),
        (PermissionLevel::Write, "\"Write\""),
        (PermissionLevel::Execute, "\"Execute\""),
        (PermissionLevel::Dangerous, "\"Dangerous\""),
    ];
    for (level, wire) in cases {
        assert_eq!(serde_json::to_string(&level).expect("serializable"), wire);
        assert_eq!(
            serde_json::from_str::<PermissionLevel>(wire).expect("deserializable"),
            level
        );
    }
}

# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! The privilege a tool call requires.

use serde::{Deserialize, Serialize};

/// Permission level required to execute a tool.
///
/// A caller (a chat channel, a scheduled job, a sub-agent) can declare a
/// maximum level; a tool whose required level exceeds it is rejected before any
/// argument is parsed.
///
/// The ordering is load-bearing: enforcement compares levels with `<`, so the
/// discriminants must stay monotonically increasing in privilege. Adding a
/// variant means deciding where in that order it sits, not appending to the
/// end.
#[derive(
    Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, Default, Hash,
)]
pub enum PermissionLevel {
    /// No permission needed — metadata-only operations.
    None = 0,
    /// Read-only operations: file reads, memory recall, listing.
    #[default]
    ReadOnly = 1,
    /// Write operations: file writes, memory stores.
    Write = 2,
    /// Command execution: shells, scripts.
    Execute = 3,
    /// Destructive or system-level operations.
    Dangerous = 4,
}

impl std::fmt::Display for PermissionLevel {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let name = match self {
            Self::None => "None",
            Self::ReadOnly => "ReadOnly",
            Self::Write => "Write",
            Self::Execute => "Execute",
            Self::Dangerous => "Dangerous",
        };
        f.write_str(name)
    }
}

