//! The declaration a model is shown for a tool.

use serde::{Deserialize, Serialize};

/// A tool as the model sees it: a name, a description, and a JSON Schema for
/// its arguments.
///
/// This is the *host-facing* declaration. It is deliberately narrower than a
/// harness's model-visible schema type, which additionally carries the
/// tool-call dialect a provider should be given. A host builds one of these
/// from a [`Tool`][crate::Tool] and lets the harness decide how to render it.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolSpec {
    /// Canonical tool name, ASCII `snake_case` by convention.
    pub name: String,
    /// Human- and model-readable description of what the tool does.
    pub description: String,
    /// JSON Schema describing the tool's arguments.
    pub parameters: serde_json::Value,
}

//! Unit tests for `ToolCallOptions` and `ToolTimeout`: their defaults and
//! that each variant stays distinct.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{ToolCallOptions, ToolTimeout};

#[test]
fn options_default_to_no_preference() {
    let options = ToolCallOptions::default();
    assert!(!options.prefer_markdown);
    assert!(ToolCallOptions::prefer_markdown().prefer_markdown);
}

#[test]
fn timeout_defaults_to_inherit() {
    assert_eq!(ToolTimeout::default(), ToolTimeout::Inherit);
    assert!(ToolTimeout::Inherit.is_inherit());
    assert!(!ToolTimeout::Unbounded.is_inherit());
    assert!(!ToolTimeout::Secs(30).is_inherit());
}

#[test]
fn timeout_variants_are_distinct() {
    assert_ne!(ToolTimeout::Inherit, ToolTimeout::Unbounded);
    assert_ne!(ToolTimeout::Secs(1), ToolTimeout::Secs(2));
}

//! Unit tests for `ToolScope` and `ToolCategory`: their defaults and the
//! wire representation each variant serializes to.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{ToolCategory, ToolScope};

#[test]
fn scope_variants_are_distinct_and_default_to_all() {
    assert_ne!(ToolScope::All, ToolScope::AgentOnly);
    assert_ne!(ToolScope::All, ToolScope::CliRpcOnly);
    assert_ne!(ToolScope::AgentOnly, ToolScope::CliRpcOnly);
    assert_eq!(ToolScope::default(), ToolScope::All);
}

#[test]
fn category_defaults_to_system() {
    assert_eq!(ToolCategory::default(), ToolCategory::System);
}

#[test]
fn category_display_matches_its_wire_form() {
    assert_eq!(ToolCategory::System.to_string(), "system");
    assert_eq!(ToolCategory::Workflow.to_string(), "skill");
}

#[test]
fn workflow_stays_pinned_to_the_skill_wire_name() {
    // Agent definition files on disk carry `"skill"`. Renaming the wire form to
    // match the Rust ident would stop those files parsing.
    assert_eq!(
        serde_json::to_string(&ToolCategory::System).expect("serializable"),
        "\"system\""
    );
    assert_eq!(
        serde_json::to_string(&ToolCategory::Workflow).expect("serializable"),
        "\"skill\""
    );
    let back: ToolCategory = serde_json::from_str("\"skill\"").expect("deserializable");
    assert_eq!(back, ToolCategory::Workflow);
}

//! Unit tests for `ToolSpec`: that it round-trips through JSON.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::ToolSpec;

#[test]
fn spec_round_trips_through_json() {
    let spec = ToolSpec {
        name: "echo".into(),
        description: "Returns its input.".into(),
        parameters: serde_json::json!({ "type": "object" }),
    };
    let encoded = serde_json::to_string(&spec).expect("serializable");
    let back: ToolSpec = serde_json::from_str(&encoded).expect("deserializable");
    assert_eq!(back.name, "echo");
    assert_eq!(back.description, "Returns its input.");
    assert_eq!(back.parameters["type"], "object");
}

#[test]
fn spec_is_pinned_to_its_literal_wire_shape() {
    // A round-trip alone only proves the encoder and decoder agree with each
    // other; it still passes if a field is silently renamed. Pin the exact
    // field names a persisted transcript or RPC payload would carry, and also
    // decode a fixed literal, so a rename is caught in both directions.
    let spec = ToolSpec {
        name: "echo".into(),
        description: "Returns its input.".into(),
        parameters: serde_json::json!({ "type": "object" }),
    };
    let encoded: serde_json::Value = serde_json::to_value(&spec).expect("serializable");
    assert_eq!(
        encoded,
        serde_json::json!({
            "name": "echo",
            "description": "Returns its input.",
            "parameters": { "type": "object" },
        })
    );

    let literal =
        r#"{"name":"echo","description":"Returns its input.","parameters":{"type":"object"}}"#;
    let decoded: ToolSpec = serde_json::from_str(literal).expect("deserializable");
    assert_eq!(decoded.name, "echo");
    assert_eq!(decoded.description, "Returns its input.");
    assert_eq!(decoded.parameters, serde_json::json!({ "type": "object" }));
}

//! Unit tests for `ToolRunContext`: the trait's defaults, and that a real
//! implementor is reachable through the erased trait object.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::{Path, PathBuf};

use super::ToolRunContext;
use crate::workspace::WorkspaceDescriptor;

/// A context that answers nothing, exercising every default.
struct Bare;
impl ToolRunContext for Bare {}

/// A context shaped like a harness's real one.
struct Isolated {
    workspace: WorkspaceDescriptor,
}

impl ToolRunContext for Isolated {
    fn workspace(&self) -> Option<&WorkspaceDescriptor> {
        Some(&self.workspace)
    }

    fn thread_id(&self) -> Option<&str> {
        Some("thread-7")
    }

    fn max_turn_output_tokens(&self) -> Option<u32> {
        Some(4096)
    }
}

#[test]
fn the_defaults_answer_nothing() {
    let bare = Bare;
    assert!(bare.workspace().is_none());
    assert!(bare.workspace_root().is_none());
    assert!(bare.workspace_policy_id().is_none());
    assert!(bare.thread_id().is_none());
    assert!(bare.max_turn_output_tokens().is_none());
}

#[test]
fn an_implementor_is_readable_through_the_trait_object() {
    let isolated = Isolated {
        workspace: WorkspaceDescriptor::new("/tmp/worktree").with_policy_id("worktree-isolation"),
    };
    let erased: &dyn ToolRunContext = &isolated;
    assert_eq!(erased.workspace_root(), Some(Path::new("/tmp/worktree")));
    assert_eq!(erased.workspace_policy_id(), Some("worktree-isolation"));
    assert_eq!(erased.thread_id(), Some("thread-7"));
    assert_eq!(erased.max_turn_output_tokens(), Some(4096));
    assert_eq!(
        erased.workspace().map(|w| w.root.clone()),
        Some(PathBuf::from("/tmp/worktree"))
    );
}

//! Unit tests for `WorkspaceDescriptor` and `SandboxMode`: the builders,
//! the JSON wire shape, and the lexical containment checks in `allows`.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::{Path, PathBuf};

use super::{SandboxMode, WorkspaceDescriptor};

#[test]
fn a_new_descriptor_is_rooted_with_no_extras() {
    let ws = WorkspaceDescriptor::new("/work/agent-a");
    assert_eq!(ws.root, PathBuf::from("/work/agent-a"));
    assert!(ws.trusted_roots.is_empty());
    assert!(ws.policy_id.is_empty());
    assert_eq!(ws.sandbox, SandboxMode::Inherit);
}

#[test]
fn the_builders_set_each_field() {
    let ws = WorkspaceDescriptor::new("/work/agent-a")
        .with_trusted_root("/shared/cache")
        .with_policy_id("worktree")
        .with_sandbox(SandboxMode::Required);
    assert_eq!(ws.trusted_roots, vec![PathBuf::from("/shared/cache")]);
    assert_eq!(ws.policy_id, "worktree");
    assert_eq!(ws.sandbox, SandboxMode::Required);
}

#[test]
fn paths_inside_the_root_or_a_trusted_root_are_allowed() {
    let ws = WorkspaceDescriptor::new("/work/agent-a").with_trusted_root("/shared/cache");
    assert!(ws.allows(Path::new("/work/agent-a/src/main.rs")));
    assert!(ws.allows(Path::new("/shared/cache/pkg")));
}

#[test]
fn paths_outside_every_root_are_refused() {
    let ws = WorkspaceDescriptor::new("/work/agent-a");
    assert!(!ws.allows(Path::new("/etc/passwd")));
    assert!(!ws.allows(Path::new("/work/agent-b/src/main.rs")));
}

#[test]
fn dot_segments_are_resolved_before_the_comparison() {
    let ws = WorkspaceDescriptor::new("/work/agent-a");
    assert!(ws.allows(Path::new("/work/agent-a/./src/../src/main.rs")));
    assert!(!ws.allows(Path::new("/work/agent-a/../agent-b/secret")));
}

#[test]
fn a_parent_traversal_cannot_spoof_re_entry_into_a_same_named_sibling() {
    // `..` must not collapse a path back onto a same-named directory outside
    // the root: dropping the escaping components is what would let
    // `agent-a/../../agent-a/secret` read as inside `/work/agent-a`.
    let ws = WorkspaceDescriptor::new("/work/nested/agent-a");
    assert!(!ws.allows(Path::new("/work/nested/agent-a/../../agent-a/secret")));
}

#[test]
fn a_parent_traversal_at_the_filesystem_root_cannot_go_higher() {
    let ws = WorkspaceDescriptor::new("/");
    assert!(ws.allows(Path::new("/../etc")));
}

#[test]
fn the_descriptor_round_trips_through_json() {
    let ws = WorkspaceDescriptor::new("/work/agent-a")
        .with_trusted_root("/shared")
        .with_policy_id("worktree")
        .with_sandbox(SandboxMode::Disabled);
    let encoded = serde_json::to_string(&ws).expect("serializable");
    let back: WorkspaceDescriptor = serde_json::from_str(&encoded).expect("deserializable");
    assert_eq!(back, ws);
}

#[test]
fn the_descriptor_is_pinned_to_its_literal_wire_shape() {
    // Same reasoning as the other pinning tests in this crate: a round-trip
    // alone doesn't catch a silent field rename, since encoder and decoder
    // still agree with each other after the rename. Assert the exact JSON
    // object a persisted config or RPC payload would carry, in both
    // directions.
    let ws = WorkspaceDescriptor::new("/work/agent-a")
        .with_trusted_root("/shared")
        .with_policy_id("worktree")
        .with_sandbox(SandboxMode::Disabled);
    let encoded: serde_json::Value = serde_json::to_value(&ws).expect("serializable");
    assert_eq!(
        encoded,
        serde_json::json!({
            "root": "/work/agent-a",
            "trusted_roots": ["/shared"],
            "policy_id": "worktree",
            "sandbox": "disabled",
        })
    );

    let literal =
        r#"{"root":"/work","trusted_roots":["/shared"],"policy_id":"p","sandbox":"required"}"#;
    let decoded: WorkspaceDescriptor = serde_json::from_str(literal).expect("deserializable");
    assert_eq!(decoded.root, std::path::PathBuf::from("/work"));
    assert_eq!(
        decoded.trusted_roots,
        vec![std::path::PathBuf::from("/shared")]
    );
    assert_eq!(decoded.policy_id, "p");
    assert_eq!(decoded.sandbox, SandboxMode::Required);
}

#[test]
fn sandbox_mode_uses_snake_case_on_the_wire() {
    assert_eq!(
        serde_json::to_string(&SandboxMode::Inherit).expect("serializable"),
        "\"inherit\""
    );
    assert_eq!(
        serde_json::to_string(&SandboxMode::Required).expect("serializable"),
        "\"required\""
    );
    assert_eq!(SandboxMode::default(), SandboxMode::Inherit);
}

#[test]
fn omitted_optional_fields_default_on_decode() {
    let back: WorkspaceDescriptor =
        serde_json::from_str(r#"{"root":"/work"}"#).expect("deserializable");
    assert_eq!(back, WorkspaceDescriptor::new("/work"));
}

//! Unit tests for `humanize_tool_name` and `context_detail_from_args`: the
//! prefix-stripping and title-casing rules, and the key-scanning, trimming,
//! and empty-value handling that produce a rendered detail.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use serde_json::json;

use super::{
    ContextDetailOptions, context_detail_from_args, context_detail_from_args_with,
    humanize_tool_name,
};

#[test]
fn snake_and_kebab_case_become_title_case() {
    assert_eq!(
        humanize_tool_name("gmail_read_message"),
        "Gmail Read Message"
    );
    assert_eq!(humanize_tool_name("web_fetch"), "Web Fetch");
    assert_eq!(humanize_tool_name("shell"), "Shell");
    assert_eq!(humanize_tool_name("read-diff"), "Read Diff");
}

#[test]
fn machine_prefixes_are_stripped() {
    // A timeline row should read as the action, not the transport that carried
    // it.
    assert_eq!(
        humanize_tool_name("composio_gmail_send_email"),
        "Gmail Send Email"
    );
    assert_eq!(
        humanize_tool_name("mcp_notion_create_page"),
        "Notion Create Page"
    );
}

#[test]
fn degenerate_names_fall_back_to_the_input() {
    assert_eq!(humanize_tool_name(""), "");
    assert_eq!(humanize_tool_name("___"), "___");
}

#[test]
fn the_most_specific_recognized_key_wins() {
    // A messaging call carries both; the recipient is the useful half.
    assert_eq!(
        context_detail_from_args(&json!({ "name": "ignored", "to": "steven@example.com" }))
            .as_deref(),
        Some("steven@example.com")
    );
}

#[test]
fn non_objects_and_unrecognized_keys_yield_nothing() {
    assert!(context_detail_from_args(&serde_json::Value::Null).is_none());
    assert!(context_detail_from_args(&json!(["a"])).is_none());
    assert!(context_detail_from_args(&json!({ "unrecognized": "x" })).is_none());
    assert!(context_detail_from_args(&json!({ "path": "" })).is_none());
    assert!(context_detail_from_args(&json!({ "path": { "nested": 1 } })).is_none());
}

#[test]
fn scalars_and_string_arrays_render() {
    assert_eq!(
        context_detail_from_args(&json!({ "id": 42 })).as_deref(),
        Some("42")
    );
    assert_eq!(
        context_detail_from_args(&json!({ "name": true })).as_deref(),
        Some("true")
    );
    assert_eq!(
        context_detail_from_args(&json!({ "to": ["a@x.com", "b@x.com"] })).as_deref(),
        Some("a@x.com, b@x.com")
    );
}

#[test]
fn blank_array_elements_do_not_survive_as_bare_punctuation() {
    // An array of only empty/whitespace strings must not render as a
    // detail at all: joining survivors with ", " and then collapsing
    // whitespace used to leave a bare "," for input like ["", "  "].
    assert_eq!(context_detail_from_args(&json!({ "to": ["", "  "] })), None);
    // A mix of blank and real entries keeps only the real ones.
    assert_eq!(
        context_detail_from_args(&json!({ "to": ["", "a@x.com", "  "] })).as_deref(),
        Some("a@x.com")
    );
}

#[test]
fn whitespace_is_collapsed() {
    assert_eq!(
        context_detail_from_args(&json!({ "command": "  ls   -la  " })).as_deref(),
        Some("ls -la")
    );
}

#[test]
fn long_values_are_elided_within_the_cap() {
    let long = "x".repeat(200);
    let detail = context_detail_from_args(&json!({ "query": long })).expect("a detail");
    assert!(detail.chars().count() <= 80);
    assert!(detail.ends_with("..."));
}

#[test]
fn a_custom_ellipsis_and_cap_are_honoured() {
    let long = "x".repeat(200);
    let detail = context_detail_from_args_with(
        &json!({ "query": long }),
        ContextDetailOptions::new(10, "…"),
    )
    .expect("a detail");
    assert_eq!(detail.chars().count(), 10);
    assert!(detail.ends_with('…'));
}

#[test]
fn an_ellipsis_longer_than_the_cap_cannot_overflow_it() {
    // A misconfigured caller must not be able to push the rendered value past
    // the cap it asked for.
    let long = "x".repeat(200);
    let detail = context_detail_from_args_with(
        &json!({ "query": long }),
        ContextDetailOptions::new(2, "..."),
    )
    .expect("a detail");
    assert_eq!(detail.chars().count(), 2);
}

#[test]
fn a_zero_cap_yields_no_detail_rather_than_a_blank_one() {
    // A degenerate `max_chars` of 0 truncates a genuinely present value down to
    // nothing; that must read as "no detail", not as "a detail, and it's
    // empty" (`Some("")`), which a caller could render as a hollow decoration.
    let detail = context_detail_from_args_with(
        &json!({ "query": "hello" }),
        ContextDetailOptions::new(0, "..."),
    );
    assert_eq!(detail, None);
}

#[test]
fn the_default_options_are_eighty_chars_and_three_dots() {
    let defaults = ContextDetailOptions::default();
    assert_eq!(defaults.max_chars, 80);
    assert_eq!(defaults.ellipsis, "...");
}
